import * as s from './style.css';

export const ImageFrame = ({
  src,
  alt,
  width,
  height,
}: {
  src: string;
  alt: string;
  width?: string;
  height?: string;
}) => {
  return (
    <div className={s.container} style={{ width, height }}>
      <img src={src} alt={alt} className={s.image} draggable={false} />
    </div>
  );
};
