import { ReactNode } from 'react';

import { Box, Typography } from '@kimdw-rtk/ui';

interface SimpleHeaderProps {
  children: ReactNode;
  name: string;
}

export const SimpleHeader = ({ children, name }: SimpleHeaderProps) => {
  return (
    <Box flex flexDirection="column" gap="lg">
      <Typography
        fontSize="sm"
        fontWeight="extraBold"
        color="primary"
        style={{ letterSpacing: '2px', textTransform: 'uppercase' }}
        as="h2"
      >
        {name}
      </Typography>
      {children}
    </Box>
  );
};
