'use client';

import { ReactNode } from 'react';

import { Box, Typography } from '@kimdw-rtk/ui';

import { ImageFrame, TechStack, techStacks } from '@/shared/components';

import * as s from './style.css';

interface ProjectSummaryProps {
  name: string;
  src: string;
  description: ReactNode;
  teckStack: Array<keyof typeof techStacks>;
  onClick?: () => void;
}

export const ProjectSummary = ({
  name,
  src,
  description,
  teckStack,
  onClick,
}: ProjectSummaryProps) => {
  return (
    <Box sx={{ flexGrow: '1', padding: 'md', backgroundColor: 'background' }}>
      <div className={s.trigger} onClick={onClick}>
        <ImageFrame src={src} alt="thumbnail" />
        <Typography
          className={s.name}
          fontSize="xl"
          fontWeight="medium"
          sx={{ marginY: 'lg' }}
        >
          {name}
        </Typography>
        <Typography fontSize="sm" color="muted-foreground" lineHeight="md">
          {description}
        </Typography>

        <Box
          flex
          gap="md"
          marginTop="2xl"
          marginBottom="lg"
          alignItems="center"
        >
          {teckStack.map((item) => (
            <TechStack key={item} type={item} />
          ))}
        </Box>
      </div>
    </Box>
  );
};
