import { Box, Separator, Typography } from '@kimdw-rtk/ui';

import { Bar, TechStack, techStacks } from '@/shared/components';

import { Project } from '.';
import { ProjectHeader } from '../ProjectHeader';
import { SimpleHeader } from '../SimpleHeader';

const techStack = [
  'TypeScript',
  'React',
  'Next.js',
  'React Query',
  'Vanilla Extract',
  'Zod',
] satisfies Array<keyof typeof techStacks>;

export const ItsoProject = () => {
  return (
    <Project name="Itso">
      <Typography fontSize="2xl" fontWeight="semiBold">
        Itso - IT 직군 채용공고 사이트
      </Typography>
      <Typography
        color="secondary-foreground"
        lineHeight="md"
        sx={{ marginTop: 'md', marginBottom: 'xl' }}
      >
        IT 직군의 채용 공고를 확인할 수 있는 사이트입니다.
        <br />
        프론트엔드 뿐만 아니라 API 서버와 크롤러를 Nest.js 기반으로
        제작하였습니다.
      </Typography>

      <Box flex flexDirection="column" gap="xl">
        {/* deployment */}
        <SimpleHeader name="deployment">
          <Typography>
            <a href="https://itso.kr/post" target="_blank">
              https://itso.kr/post
            </a>
          </Typography>
        </SimpleHeader>

        {/* github */}
        <SimpleHeader name="github">
          <Typography>
            <a href="https://github.com/kimdw524/itso" target="_blank">
              https://github.com/kimdw524/itso
            </a>
          </Typography>
        </SimpleHeader>

        {/* duration */}
        <SimpleHeader name="duration">
          <Typography>2025. 07 ~ 진행 중</Typography>
        </SimpleHeader>

        {/* team */}
        <SimpleHeader name="team">
          <Typography>개인 프로젝트 (100%)</Typography>
        </SimpleHeader>

        {/* tech stack */}
        <SimpleHeader name="tech stack">
          <Box flex gap="md" marginBottom="lg" alignItems="center">
            <Separator separator={<Bar />}>
              {techStack.map((item) => (
                <Box
                  flex
                  flexWrap="wrap"
                  alignItems="center"
                  gap="sm"
                  key={item}
                >
                  <TechStack type={item} />
                  <Typography fontSize="sm">{item}</Typography>
                </Box>
              ))}
            </Separator>
          </Box>
        </SimpleHeader>
      </Box>

      {/* features */}
      <ProjectHeader>Features</ProjectHeader>
      <Box flex flexDirection="column" gap="3xl" color="foreground">
        {/* 채용 공고 조회 */}
        <Box>
          <Typography
            fontSize="2xl"
            fontWeight="semiBold"
            as="h3"
            sx={{ marginBottom: 'xl' }}
          >
            1. 채용 공고 조회
          </Typography>
          <div style={{ marginBottom: '1rem', textAlign: 'center' }}>
            <img src="./images/itso_3.png" alt="image3" width="550px" />
          </div>
          <Typography>
            여러 검색 조건을 바탕으로 원하는 채용 공고를 보여주는 기능입니다.
          </Typography>
          <Typography fontSize="lg" fontWeight="semiBold" as="h4">
            검색 API 필터 - useSearchParams 개선
          </Typography>
          <div style={{ marginBottom: '1rem', textAlign: 'center' }}>
            <img src="./images/itso_2.png" alt="image2" width="550px" />
          </div>
          <Typography lineHeight="lg">
            API 인터페이스를 제네릭으로 제공하면 API의 SearchParams를
            type-safe하게 관리할 수 있는 hook을 구현하였습니다.
            <br />또 API와 브라우저의 SearchParams를 동기화 시켜 새로고침을 해도
            검색 필터가 유지되도록 하였습니다.
            <br />
            그러나 브라우저에서{' '}
            <mark>
              API 형식에 맞지 않는 SearchParams를 사용자가 임의로 입력할 수 있는
              문제
            </mark>
            가 발생했고
            <br />
            이를 런타임 유효성 검증 라이브러리인 <mark>Zod</mark>를 통해
            해결하였습니다.
            <br />
            <br />
            이미 <mark>@tanstack/react-router</mark>에 SearchParams를
            type-safe하게 관리할 수 있는 기능이 존재하지만,
            <br />
            해당 기능은 특정 라우터를 적용한 환경에서만 사용할 수 있다는 제약이
            있습니다.
            <br />
            또, TypeScript 환경에서 개발자가 직접 SearchParam을 변경할 경우 타입
            안정성이 보장되지만,
            <br />
            매번 유효성 검증을 진행하여 불필요한 연산이 추가적으로 발생한다는
            단점이 있었고, 이를 개선하여 기능을 구현하였습니다.
          </Typography>

          <Typography fontSize="lg" fontWeight="semiBold" as="h4">
            SSR 및 무한 스크롤
          </Typography>
          <Typography lineHeight="lg">
            SSR을 적용하여 렌더링 지표 개선 및 React Query useInfiniteQuery +
            IntersectionObserver API를 활용한 무한 스크롤을 구현하였습니다.
            <br />
            또, fade-in 애니메이션을 적용하여 로딩 화면(Skeleton UI)과 실제 화면
            간의 전환을 부드럽게 구현하였습니다.
          </Typography>
        </Box>

        {/* 로깅 */}
        <Box>
          <Typography
            fontSize="2xl"
            fontWeight="semiBold"
            as="h3"
            sx={{ marginBottom: 'xl' }}
          >
            2. 로깅
          </Typography>
          <Typography fontSize="lg" fontWeight="semiBold" as="h4">
            로깅 컴포넌트
          </Typography>
          <Typography lineHeight="lg">
            '공유하기'처럼 서버 API 호출을 하지 않는 기능이나 하이퍼링크처럼
            별다른 이벤트 핸들러가 없는 곳에도 클릭 로그가 필요한 경우가
            존재합니다.
            <br />
            이러한 곳에서 로그를 남길 수 있을 뿐만 아니라 선언적으로 코드를
            작성할 수 있는 로깅 컴포넌트를 구현하였습니다.
            <br />
            element를 래핑하여 로깅을 하는 방식은{' '}
            <mark>CSS 레이아웃이 깨지거나 HTML 명세를 위반</mark>할 수 있습니다.
            <br />
            이를 방지하기 위해 <mark>cloneElement</mark>를 활용하여 원본
            element에 이벤트 핸들러를 주입하는 방식을 선택했습니다.
          </Typography>
          <Typography fontSize="lg" fontWeight="semiBold" as="h4">
            서버 컴포넌트에서 사용자 IP 수집하기
          </Typography>
          <Typography lineHeight="lg">
            서버 컴포넌트에서 호출하는 API는 Next.js 서버를 통해 호출되기 때문에
            사용자의 IP를 알 수 없는 문제가 있습니다.
            <br />
            클라이언트, 서버 컴포넌트 두 곳 모두에서 호출되는 API가 존재했기에
            IP를 API body에 보내는 방법은 적절하지 않았습니다.
            <br />
            nginx X-Forwarded-For 헤더를 활용하여, 서버 컴포넌트에서 API 요청 시
            XFF에 클라이언트의 IP를 추가하고
            <br />
            서버에서는 Next.js 서버 IP의 XFF 헤더를 신뢰하는 방식으로 IP를
            수집하였습니다.
          </Typography>
        </Box>
      </Box>

      {/* trouble shootings */}
      <ProjectHeader>Trouble shootings</ProjectHeader>

      <Box color="foreground">
        <Typography
          fontSize="2xl"
          fontWeight="semiBold"
          as="h3"
          sx={{ marginBottom: 'xl' }}
        >
          1. position: sticky stuck 상태 감지
        </Typography>
        <Typography lineHeight="lg">
          IntersectionObserver API를 활용하여 position: sticky 요소의 stuck
          상태를 감지하였습니다.
          <br />
          하지만{' '}
          <mark>
            미디어 쿼리에 의해 sticky 요소의 top이 변경되면 stuck 상태를 감지할
            수 없는 문제
          </mark>
          가 발생하였습니다.
          <br />
          해당 문제를 성능과 반응 속도 모두 뛰어난 방법을 찾기 위해 여러 방법을
          고민하였습니다.
        </Typography>
        <ol>
          <li>
            <Typography lineHeight="lg">
              <b>window resize 이벤트 활용하기</b>
              <br />
              resize 이벤트의 잦은 발생으로 인한 성능적인 단점이 존재했고
              <br />
              이를 해결하기 위해 쓰로틀링이나 디바운싱을 적용할 경우 stuck 상태
              감지에 지연이 발생하여 적합하지 않았습니다.
            </Typography>
          </li>
          <li>
            <Typography lineHeight="lg">
              <b>window.matchMedia() 활용하기</b>
              <br />
              미디어 쿼리로 인한 top 변경이 아닌, 클래스/인라인 스타일 적용으로
              인한 top 변경을 감지하지 못한다는 문제가 존재합니다.
            </Typography>
          </li>
          <li>
            <Typography lineHeight="lg">
              <b>transition을 활용한 트릭</b>
              <br />
              'transition: top 1ms' 스타일을 적용 후 transitionstart 이벤트에
              IntersectionObserver API를 새로운 top 기준으로 다시 적용합니다.
            </Typography>
          </li>
        </ol>
        <Typography lineHeight="lg">
          transition을 활용하는 방법이 가장 적절한 방법이라고 생각하여
          적용하였고 sticky 요소의 top 값의 변화를 즉각적으로 감지할 수
          있었습니다.
        </Typography>
      </Box>
    </Project>
  );
};
