import { Tooltip } from '@kimdw-rtk/ui';

import * as s from './style.css';

export const techStacks = {
  React: './images/react.png',
  'Next.js': './images/nextjs.png',
  Jotai: './images/jotai.png',
  'Vanilla Extract': './images/vanilla-extract.png',
  TypeScript: './images/typescript.png',
  Zod: './images/zod.png',
  'React Query': './images/react-query.png',
  Jest: './images/jest.png',
  'React Testing Library': './images/react-testing-library.png',
  Storybook: './images/storybook.png',
  JavaScript: './images/javascript.png',
} as const;

interface TeckStackProps {
  type: keyof typeof techStacks;
}

export const TechStack = ({ type }: TeckStackProps) => {
  return (
    <div className={s.container}>
      <Tooltip content={type}>
        <img
          src={techStacks[type]}
          alt={type}
          className={s.icon}
          draggable={false}
        />
      </Tooltip>
    </div>
  );
};
