import {
  Accordion,
  AccordionContent,
  AccordionTrigger,
  Box,
  Separator,
  Typography,
} from '@kimdw-rtk/ui';

import { Bar, TechStack, techStacks } from '@/shared/components';

import { Project } from '.';
import { ProjectHeader } from '../ProjectHeader';
import { SimpleHeader } from '../SimpleHeader';

const techStack = [
  'TypeScript',
  'React',
  'Next.js',
  'Jotai',
  'Vanilla Extract',
  'Jest',
  'React Testing Library',
  'Storybook',
] satisfies Array<keyof typeof techStacks>;

export const CoinfoProject = () => {
  return (
    <Project name="Coinfo">
      <Typography fontSize="2xl" fontWeight="semiBold">
        Coinfo - 실시간 암호화폐 시세 사이트
      </Typography>
      <Typography
        color="secondary-foreground"
        lineHeight="md"
        sx={{ marginTop: 'md', marginBottom: 'xl' }}
      >
        여러 암호화폐 거래소의 WebSocket API를 활용하여 실시간 시세를 보여주고,
        국내외 거래소 간의 시세 차이를 계산해주는 사이트입니다.
        <br />
        많은 페이지를 구현하는 것보다 잦은 렌더링 발생이 불가피 할 때 적용할 수
        있는 최적화를 고민하고
        <br />
        여러 프로젝트에서 범용적으로 사용할 수 있는 패키지를 구현하는 것에
        초점을 맞추어 프로젝트를 진행하였습니다.
      </Typography>

      <Box flex flexDirection="column" gap="xl">
        {/* deployment */}
        <SimpleHeader name="deployment">
          <Typography>
            <a href="https://coinfo-web.vercel.app" target="_blank">
              https://coinfo-web.vercel.app
            </a>
          </Typography>
        </SimpleHeader>

        {/* github */}
        <SimpleHeader name="github">
          <Typography>
            <a href="https://github.com/kimdw524/coinfo" target="_blank">
              https://github.com/kimdw524/coinfo
            </a>
          </Typography>
        </SimpleHeader>

        {/* duration */}
        <SimpleHeader name="duration">
          <Typography>2025. 04 ~ 2025. 06</Typography>
        </SimpleHeader>

        {/* team */}
        <SimpleHeader name="team">
          <Typography>개인 프로젝트 (100%)</Typography>
        </SimpleHeader>

        {/* tech stack */}
        <SimpleHeader name="tech stack">
          <Box flex gap="md" marginBottom="lg" alignItems="center">
            <Separator separator={<Bar />}>
              {techStack.map((item) => (
                <Box
                  flex
                  flexWrap="wrap"
                  alignItems="center"
                  gap="sm"
                  key={item}
                >
                  <TechStack type={item} />
                  <Typography fontSize="sm">{item}</Typography>
                </Box>
              ))}
            </Separator>
          </Box>
        </SimpleHeader>
      </Box>

      {/* features */}
      <ProjectHeader>Features</ProjectHeader>
      <Box flex flexDirection="column" gap="3xl" color="foreground">
        {/* 실시간 시세 */}
        <Box>
          <Typography
            fontSize="2xl"
            fontWeight="semiBold"
            as="h3"
            sx={{ marginBottom: 'xl' }}
          >
            1. 실시간 시세
          </Typography>
          <div style={{ marginBottom: '1rem', textAlign: 'center' }}>
            <img src="./images/coinfo_2.png" alt="image1" width="550px" />
          </div>
          <Typography>
            여러 암호화폐 거래소의 WebSocket API를 활용하여 실시간 시세를
            보여주고, 각 거래소의 가격 차이를 계산하는 기능입니다.
          </Typography>
          <Typography fontSize="lg" fontWeight="semiBold" as="h4">
            렌더링 최적화
          </Typography>
          <Typography lineHeight="lg">
            실시간 시세의 잦은 렌더링으로 인하여 성능 저하가 발생하였고, 이를
            최적화하기 위한 방법을 고민하였습니다. <br />
            일반적으로 잦은 함수 호출은 쓰로틀링을 통해 최적화를 하나, 아래와
            같은 이유로 <mark>쓰로틀링이 적합하지 않다고</mark> 판단하였습니다.
          </Typography>
          <ol>
            <li>
              시세 종목이 100개가 넘기 때문에, 각 종목에 쓰로틀링을 적용해도
              효과가 미미합니다.
            </li>
            <li>
              실시간성이 매우 중요한 기능에 쓰로틀링은 적합하지 않다고
              생각하였습니다.
            </li>
          </ol>
          <Typography lineHeight="lg">
            대신, 제한적인 화면 크기로 인해 사용자가 일부 시세만 확인할 수
            있다는 점을 활용하고자 하였습니다.
            <br />
            <mark>
              Viewport에 존재하기 전까지 렌더링을 지연하는 HOC를 구현
            </mark>{' '}
            후 적용하여{' '}
            <mark>렌더링 성능을 2.8배 향상시키고, 실시간성을 유지</mark>할 수
            있었습니다.
            <br />
            추가적으로,{' '}
            <mark>
              렌더링을 지연함으로써 발생할 수 있는 layout shift를 고려
            </mark>
            하여 최초 1회는 반드시 컴포넌트를 렌더링 하도록 구현하였습니다.
          </Typography>
          <Accordion isPadding={false} style={{ borderBottom: '0' }}>
            <AccordionTrigger iconPosition="text">
              withInViewport.tsx 코드 보기
            </AccordionTrigger>
            <AccordionContent>
              <img
                src="./images/coinfo_3.png"
                alt="image3"
                style={{ width: '100%' }}
              />
            </AccordionContent>
          </Accordion>
        </Box>

        {/* 디자인 시스템 */}
        <Box>
          <Typography
            fontSize="2xl"
            fontWeight="semiBold"
            as="h3"
            sx={{ marginBottom: 'xl' }}
          >
            2. CSS
          </Typography>
          <Typography fontSize="lg" fontWeight="semiBold" as="h4">
            CSS 미디어 쿼리 자동화 PostCSS 플러그인 구현
          </Typography>
          <Typography lineHeight="lg">
            모바일 환경에서 CSS :hover의 동작이 UX를 저해한다고 느껴, 이를
            제거하거나 :active로 대신하여 스타일을 적용하려고 했습니다.
            <br />
            이는 미디어 쿼리를 통해 해결할 수 있으나 작성해야 하는 CSS의 양이
            크게 늘어나고
            <br />
            가독성 측면에서 좋지 못하다고 생각하여 이를 자동으로 처리해 주는
            PostCSS 플러그인을 구현하였습니다.
          </Typography>
          <div style={{ textAlign: 'center' }}>
            <img
              src="./images/coinfo_4.png"
              alt="image4"
              style={{ width: '450px' }}
            />
          </div>
        </Box>
      </Box>

      {/* trouble shootings */}
      <ProjectHeader>Trouble shootings</ProjectHeader>

      <Box color="foreground">
        <Typography
          fontSize="2xl"
          fontWeight="semiBold"
          as="h3"
          sx={{ marginBottom: 'xl' }}
        >
          1. Vanilla Extract sprinkles (유틸리티 클래스) CSS 우선순위 문제
        </Typography>
        <Typography lineHeight="lg">
          Vanilla Extract는 sprinkles() 함수를 통해 유틸리티 클래스를 정의할 수
          있습니다.
          <br />
          그러나 아래 예시처럼 컴포넌트의 기존 스타일과 겹칠 경우 유틸리티
          클래스의 스타일이 적용되지 않는 문제가 발생했습니다.
        </Typography>
        <div style={{ textAlign: 'center' }}>
          <img
            src="./images/coinfo_6.png"
            alt="image6"
            style={{ width: '700px' }}
          />
        </div>
        <Typography lineHeight="lg">
          <u>External CSS의 경우 늦게 정의된 클래스가 우선순위가 높기</u> 때문에
          <br />
          <u>sprinkles 스타일이 다른 스타일보다 먼저 정의되어</u> 우선순위가
          밀리는 현상이 발생했습니다.
          <br />
          이를 해결하기 위해 아래와 같은 두 가지 방법을 고안하였습니다.
        </Typography>
        <ol>
          <li>
            <Typography lineHeight="lg">
              <b>sprinkles CSS 먼저 정의하기 ❌</b>
              <br />
              Vanilla Extract는 스타일 관련 함수가 호출되는 순서대로 클래스가
              CSS 파일에 추가됩니다.
              <br />
              sprinkles() 함수를 다른 style() 함수보다 먼저 호출하는 것은
              번들러의 Entry point에 가까운 곳에서 호출하면 되는 간단한 일이지만
              <br />
              반대로 나중에 호출하여 CSS 우선순위를 높이는 것은 현재 구조상
              불가능하다고 판단하였습니다.
            </Typography>
          </li>
          <li>
            <Typography lineHeight="lg">
              <b>CSS @layer + 헬퍼 함수 구현하기 ✅</b>
              <br />
              CSS @layer를 통해 우선순위를 변경함으로써 문제를 해결할 수
              있었으나 Vanilla Extract의 recipe() 함수를 사용하는 경우
              <br />
              하나의 컴포넌트 스타일을 정의하는 데 layer를 반복적으로 명시해야
              하므로 DX가 크게 저하됐습니다. (코드 약 30% 증가)
              <br />
              이를 recipe 내 모든 클래스의 layer를 명시해주는
              recipeWithLayer()라는 헬퍼 함수를 정의함으로써 해결하였습니다.
            </Typography>
          </li>
        </ol>
      </Box>
    </Project>
  );
};
