'use client';

import { ReactNode } from 'react';

import { Dialog, DialogContent, DialogHeader } from '@kimdw-rtk/ui';
import { useOverlay } from '@kimdw-rtk/utils';

interface ProjectProps {
  children: ReactNode;
  name: string;
}

export const Project = ({ children, name }: ProjectProps) => {
  const { close } = useOverlay();

  return (
    <Dialog style={{ width: '1024px' }}>
      <DialogHeader onCloseClick={close}>{name}</DialogHeader>
      <DialogContent>{children}</DialogContent>
    </Dialog>
  );
};
