'use client';

import { useOverlay } from '@kimdw-rtk/utils';

import { CoinfoProject } from '../Project/CoinfoProject';
import { ItsoProject } from '../Project/ItsoProject';
import { ReactKitsProject } from '../Project/ReactKitsProject';
import { ProjectSummary } from '../ProjectSummary';
import * as s from './style.css';

export const ProjectSection = () => {
  const { push } = useOverlay();

  return (
    <section>
      <div className={s.container}>
        <ProjectSummary
          name="react-kits"
          src="./images/react-kits_1.png"
          description="디자인 시스템, Animation, Overlay 및 지금까지 프로젝트를 진행하면서 구현했던 React 유틸을 모아둔 라이브러리입니다."
          teckStack={[
            'TypeScript',
            'React',
            'Vanilla Extract',
            'Jest',
            'React Testing Library',
          ]}
          onClick={() => push(<ReactKitsProject />)}
        />
        <ProjectSummary
          name="Itso - IT 직군 채용공고 사이트"
          src="./images/itso_1.png"
          description="IT 직군 채용공고를 확인할 수 있는 사이트입니다."
          teckStack={[
            'TypeScript',
            'React',
            'Next.js',
            'React Query',
            'Vanilla Extract',
            'Zod',
          ]}
          onClick={() => push(<ItsoProject />)}
        />
        <ProjectSummary
          name="Coinfo - 암호화폐 실시간 시세 사이트"
          src="./images/coinfo_1.png"
          description="여러 암호화폐 거래소의 WebSocket API를 활용하여 실시간 시세를 보여주고,국내외 거래소 간의 시세 차이를 계산해주는 사이트입니다."
          teckStack={[
            'TypeScript',
            'React',
            'Next.js',
            'Jotai',
            'Vanilla Extract',
            'Jest',
            'React Testing Library',
            'Storybook',
          ]}
          onClick={() => push(<CoinfoProject />)}
        />
      </div>
    </section>
  );
};
