import type { HeadFC, PageProps } from 'gatsby';

import { Box, Container } from '@kimdw-rtk/ui';

import { Header, Info, Skill } from '@/features/home/components';
import { ProjectSection } from '@/features/project/components';
import { Section } from '@/shared/components';
import '@/shared/styles/glboalStyle.css';

const IndexPage: React.FC<PageProps> = () => {
  return (
    <main>
      <Container size="md" padding="2xl">
        <Header />
        <Box marginY="md">
          <Info />
        </Box>
        {/* <Box marginY="lg">
          <Intro />
        </Box> */}
        <Section>SKILL</Section>
        <Skill />
        <Section>PROJECT</Section>
        <ProjectSection />
      </Container>
      <script
        data-goatcounter="https://kimdw524.goatcounter.com/count"
        src="//gc.zgo.at/count.js"
        async
      ></script>
    </main>
  );
};

export default IndexPage;

export const Head: HeadFC = () => (
  <>
    <title>kimdw524's portfolio</title>
  </>
);
