import { ReactNode } from 'react';

import { Box, Typography } from '@kimdw-rtk/ui';

import { Line } from '@/shared/components';

export const ProjectHeader = ({ children }: { children: ReactNode }) => {
  return (
    <Box flex flexDirection="row" alignItems="center" gap="md">
      <Typography
        fontWeight="extraBold"
        fontSize="lg"
        color="primary"
        sx={{ marginY: 'xl' }}
        style={{ letterSpacing: '2px', textTransform: 'uppercase' }}
        as="h2"
      >
        {children}
      </Typography>
      <Line />
    </Box>
  );
};
